/** A frame of a tool kind: where it is in the group's sheet (x, y, width, height) and where it goes on the panel (x, y). */
export type KindCell = readonly [number, number, number, number, number, number];

export interface KindScripts {
  /** Cell indices, a step each: laid back in its mold; picked up; a wiggle in the mold when pointed at. */
  putDown: readonly number[];
  pickUp: readonly number[];
  wiggle: readonly number[];
  /** The clip each of the three plays. */
  sounds: readonly [string, string, string];
}

export interface KindGroup {
  /** The molded panel's size, and the sheet's. */
  panel: readonly [number, number];
  sheet: readonly [number, number];
  cells: readonly KindCell[];
  kinds: readonly KindScripts[];
}

